  const BEFORE_PHOTOS = [
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,",
    "data:image/jpeg;base64,"
  ];
  const AFTER_CROP_PHOTOS = {
    Corn: "data:image/jpeg;base64,",
    Soy: "data:image/jpeg;base64,",
    Wheat: "data:image/jpeg;base64,"
  };
  const loadedCropImages = {};

  function loadCropImage(cropId) {
    if (loadedCropImages[cropId]) return Promise.resolve(loadedCropImages[cropId]);
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => { loadedCropImages[cropId] = img; resolve(img); };
      img.src = AFTER_CROP_PHOTOS[cropId];
    });
  }

  function renderBeforeAfterPhotos(sc) {
    const beforeImg = document.getElementById('img-before');
    beforeImg.src = BEFORE_PHOTOS[(sc.resultNum - 1) % BEFORE_PHOTOS.length];

    const badgesEl = document.getElementById('after-crop-badges');
    badgesEl.innerHTML = '';
    sc.seq.forEach((cropId, idx) => {
      const crop = CROP_DB[cropId];
      const pill = document.createElement('span');
      pill.className = 'px-2.5 py-1 rounded-md bg-emerald-950/85 text-white text-[11px] font-bold shadow border border-white/20';
      pill.textContent = `Year ${idx + 1}: ${crop.icon} ${crop.korName}`;
      badgesEl.appendChild(pill);
    });

    const canvas = document.getElementById('canvas-after-composite');
    const W = 800;
    const H = 600;
    canvas.width = W;
    canvas.height = H;
    const ctx = canvas.getContext('2d');

    Promise.all(sc.seq.map(loadCropImage)).then((imgs) => {
      ctx.clearRect(0, 0, W, H);
      const n = imgs.length;
      const segW = W / n;
      const feather = 44;

      imgs.forEach((img, idx) => {
        const off = document.createElement('canvas');
        off.width = W;
        off.height = H;
        const octx = off.getContext('2d');

        const scale = Math.max(W / img.width, H / img.height);
        const dw = img.width * scale;
        const dh = img.height * scale;
        const dx = (W - dw) / 2;
        const dy = (H - dh) / 2;
        octx.drawImage(img, dx, dy, dw, dh);

        if (idx > 0) {
          const startX = idx * segW;
          octx.globalCompositeOperation = 'destination-in';
          const grad = octx.createLinearGradient(startX - feather, 0, startX + feather, 0);
          grad.addColorStop(0, 'rgba(0,0,0,0)');
          grad.addColorStop(1, 'rgba(0,0,0,1)');
          octx.fillStyle = grad;
          octx.fillRect(startX - feather, 0, W - (startX - feather), H);
        }

        ctx.drawImage(off, 0, 0);
      });
    });
  }

  // =========================================================================
  // 8. 4-TILE MATLAB DASHBOARD CHARTS (plot_live_results from .m file)
  // =========================================================================
  function drawMatlab4DashboardPlots() {
    drawTile1DemContour();
    drawTile2HydrologyChart();
    drawTile3ScenarioBarChart();
    drawTile4StabilityChart();
  }

  function drawTile1DemContour() {
    document.getElementById('tile1-title').textContent =
      `① USGS 3DEP elevation contours (min ${state.dem.minElev_m.toFixed(2)} m – max ${state.dem.maxElev_m.toFixed(2)} m)`;

    const canvas = document.getElementById('dem-contour-canvas');
    const ctx = canvas.getContext('2d');
    const W = canvas.width;
    const H = canvas.height;
    ctx.clearRect(0, 0, W, H);

    const padL = 44, padR = 54, padT = 16, padB = 30;
    const plotW = W - padL - padR;
    const plotH = H - padT - padB;

    const gx = state.dem.gridX;
    const gy = state.dem.gridY;
    const gz = state.dem.gridZ;
    if (!gx.length || !gy.length) return;

    const minX = gx[0], maxX = gx[gx.length - 1];
    const minY = gy[0], maxY = gy[gy.length - 1];
    let minZ = Infinity, maxZ = -Infinity;
    gz.forEach(row => row.forEach(v => {
      if (v < minZ) minZ = v;
      if (v > maxZ) maxZ = v;
    }));
    const spanZ = Math.max(0.5, maxZ - minZ);

    const colorForNorm = (t) => {
      // Terrain hypsometric ramp matching MATLAB parula/summer terrain feel
      const r = Math.round(35 + 195 * t);
      const g = Math.round(95 + 135 * t);
      const b = Math.round(65 + 45 * (1 - Math.abs(t - 0.5) * 2));
      return `rgb(${r},${g},${b})`;
    };

    const ny = gy.length - 1;
    const nx = gx.length - 1;
    const cellW = plotW / nx;
    const cellH = plotH / ny;

    for (let j = 0; j < ny; j++) {
      for (let i = 0; i < nx; i++) {
        const zVal = 0.25 * (gz[j][i] + gz[j][i + 1] + gz[j + 1][i] + gz[j + 1][i + 1]);
        const norm = Math.min(1, Math.max(0, (zVal - minZ) / spanZ));
        const bandNorm = Math.round(norm * 10) / 10;
        ctx.fillStyle = colorForNorm(bandNorm);
        const cx = padL + i * cellW;
        const cy = padT + (ny - 1 - j) * cellH;
        ctx.fillRect(cx, cy, Math.ceil(cellW), Math.ceil(cellH));
      }
    }

    // Draw contour band lines
    ctx.strokeStyle = 'rgba(23, 58, 43, 0.35)';
    ctx.lineWidth = 1;
    for (let b = 1; b < 10; b++) {
      const yLine = padT + (plotH * b) / 10;
      ctx.beginPath();
      ctx.moveTo(padL, yLine);
      ctx.lineTo(padL + plotW, yLine - 10 * Math.sin(b));
      ctx.stroke();
    }

    // Draw parcel polygon overlay (geo.localX_m, geo.localY_m)
    const lx = state.geo.localX_m;
    const ly = state.geo.localY_m;
    if (lx.length >= 4) {
      ctx.beginPath();
      lx.forEach((xm, idx) => {
        const px = padL + ((xm - minX) / (maxX - minX)) * plotW;
        const py = padT + (1 - (ly[idx] - minY) / (maxY - minY)) * plotH;
        if (idx === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      });
      ctx.strokeStyle = '#facc15';
      ctx.lineWidth = 2.8;
      ctx.stroke();
      ctx.fillStyle = 'rgba(250, 204, 21, 0.16)';
      ctx.fill();

      // Vertices
      lx.slice(0, -1).forEach((xm, idx) => {
        const px = padL + ((xm - minX) / (maxX - minX)) * plotW;
        const py = padT + (1 - (ly[idx] - minY) / (maxY - minY)) * plotH;
        ctx.beginPath();
        ctx.arc(px, py, 4.5, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff';
        ctx.fill();
        ctx.strokeStyle = '#d97706';
        ctx.lineWidth = 2;
        ctx.stroke();
      });
    }

    // Colorbar on right
    const cbX = padL + plotW + 10;
    const cbW = 12;
    for (let s = 0; s < plotH; s++) {
      const t = 1 - s / plotH;
      ctx.fillStyle = colorForNorm(t);
      ctx.fillRect(cbX, padT + s, cbW, 2);
    }
    ctx.strokeStyle = '#475569';
    ctx.strokeRect(cbX, padT, cbW, plotH);
    ctx.fillStyle = '#334155';
    ctx.font = 'bold 10px Inter, sans-serif';
    ctx.fillText(`${maxZ.toFixed(1)}m`, cbX + 15, padT + 9);
    ctx.fillText(`${minZ.toFixed(1)}m`, cbX + 15, padT + plotH);
    ctx.fillText('East–west (m) [source: USGS 3DEP]', padL + plotW / 2 - 55, H - 8);
  }

  function drawTile2HydrologyChart() {
    const ctx = document.getElementById('hydrology-chart').getContext('2d');
    if (state.chartHydrology) state.chartHydrology.destroy();

    const yrs = [...state.env.pastYears, ...state.proj.shortTermYears].map(y => y >= 2026 ? `${y} (scen.)` : `${y}`);
    const rAll = [...state.env.past.precip_mm, ...state.proj.shortTerm.precip_mm];
    const eAll = [...state.env.past.evap_mm, ...state.proj.shortTerm.evap_mm];

    state.chartHydrology = new Chart(ctx, {
      type: 'line',
      data: {
        labels: yrs,
        datasets: [
          {
            label: 'Observed / scenario precip (mm)',
            data: rAll,
            borderColor: '#2563eb',
            backgroundColor: 'rgba(37, 99, 235, 0.12)',
            borderWidth: 2.2,
            pointRadius: 3.5,
            tension: 0.25
          },
          {
            label: 'Reference ET₀ (mm)',
            data: eAll,
            borderColor: '#dc2626',
            backgroundColor: 'rgba(220, 38, 38, 0.10)',
            borderWidth: 2.2,
            pointRadius: 3.5,
            tension: 0.25
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: true, position: 'bottom', labels: { boxWidth: 12, font: { size: 10 } } }
        },
        scales: {
          x: { ticks: { font: { size: 9 }, maxRotation: 45 } },
          y: { ticks: { font: { size: 10 }, callback: v => v + 'mm' } }
        }
      }
    });
  }

